-- Resumable uploads organ -- generated by noctusai_lib.domain.resumable_uploads.sql
SET search_path = social_wiring, public;

CREATE TABLE IF NOT EXISTS social_wiring.upload_sessions (
    id           UUID PRIMARY KEY,
    org_id       UUID NOT NULL,
    user_id      UUID,
    filename     TEXT NOT NULL,
    content_type TEXT NOT NULL,
    size_bytes   BIGINT NOT NULL CHECK (size_bytes > 0),
    part_size    INTEGER NOT NULL CHECK (part_size > 0),
    total_parts  INTEGER NOT NULL CHECK (total_parts > 0),
    status       TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','completed','aborted','expired')),
    client_key   TEXT,
    object_key   TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ
);
COMMENT ON TABLE social_wiring.upload_sessions IS 'tier:org';
CREATE INDEX IF NOT EXISTS upload_sessions_org_key_idx ON social_wiring.upload_sessions (org_id, client_key) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS upload_sessions_expiry_idx ON social_wiring.upload_sessions (expires_at) WHERE status = 'open';

CREATE TABLE IF NOT EXISTS social_wiring.upload_session_events (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    org_id      UUID NOT NULL,
    session_id  UUID NOT NULL REFERENCES social_wiring.upload_sessions(id) ON DELETE CASCADE,
    kind        TEXT NOT NULL CHECK (kind IN ('opened','completed','aborted','expired')),
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    detail      JSONB NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE social_wiring.upload_session_events IS 'tier:org';
CREATE INDEX IF NOT EXISTS upload_session_events_session_idx ON social_wiring.upload_session_events (session_id, occurred_at);

ALTER TABLE social_wiring.upload_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE social_wiring.upload_session_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "service_role_bypass" ON social_wiring.upload_sessions;
CREATE POLICY "service_role_bypass" ON social_wiring.upload_sessions FOR ALL TO service_role USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "service_role_bypass" ON social_wiring.upload_session_events;
CREATE POLICY "service_role_bypass" ON social_wiring.upload_session_events FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON social_wiring.upload_sessions FROM PUBLIC, anon, authenticated;
REVOKE ALL ON social_wiring.upload_session_events FROM PUBLIC, anon, authenticated;
GRANT ALL ON social_wiring.upload_sessions TO service_role;
GRANT ALL ON social_wiring.upload_session_events TO service_role;
